buggy.timedelta_kwargs_inf_behavior:
import numpy as np
from pandas import Timedelta

# Test various unit kwargs with inf
for unit in ['days', 'weeks', 'hours', 'minutes', 'seconds', 'milliseconds', 'microseconds', 'nanoseconds']:
    try:
        kwargs = {unit: np.inf}
        result = Timedelta(**kwargs)
        probe(f'timedelta_{unit}_inf', 'no_error')
    except Exception as e:
        probe(f'timedelta_{unit}_inf', type(e).__name__)

# Test negative inf
try:
    result = Timedelta(days=-np.inf)
    probe('timedelta_neg_inf', 'no_error')
except Exception as e:
    probe('timedelta_neg_inf', type(e).__name__)

buggy.to_datetime_inf_behavior:
import numpy as np
import pandas as pd

# Test to_datetime with infinite hour field
try:
    df = pd.DataFrame({
        'year': [2000, 2000],
        'month': [1, 1],
        'day': [1, 1],
        'hour': [12.0, np.inf]
    })
    result = pd.to_datetime(df, errors='coerce')
    probe('to_datetime_inf_hour', 'no_error')
except Exception as e:
    probe('to_datetime_inf_hour', type(e).__name__)

# Also test with direct values
try:
    result = pd.to_datetime({'year': [2000, 2000], 'month': [1, 1], 'day': [1, 1], 'hour': [12.0, np.inf]}, errors='coerce')
    probe('to_datetime_inf_dict', 'no_error')
except Exception as e:
    probe('to_datetime_inf_dict', type(e).__name__)
